using System.Runtime.InteropServices;

public static partial class NativeCompression
{
    [LibraryImport("compresslib")]
    public static partial int CompressBuffer(
        [In] ReadOnlySpan<byte> input,
        nuint inputLen,
        Span<byte> output,
        nuint outputLen,
        out nuint bytesWritten);

    [DllImport("compresslib", EntryPoint = "compress_buffer", ExactSpelling = true)]
    private static extern int CompressBufferRaw(
        IntPtr input, nuint inputLen,
        IntPtr output, nuint outputLen,
        out nuint bytesWritten);

    /// <summary>
    /// Compresses <paramref name="input"/> into <paramref name="output"/>.
    /// Returns the native status code and sets <paramref name="bytesWritten"/>
    /// to the number of bytes written to the output buffer.
    /// </summary>
    public static int Compress(ReadOnlySpan<byte> input, Span<byte> output, out nuint bytesWritten)
    {
        return CompressBuffer(input, (nuint)input.Length, output, (nuint)output.Length, out bytesWritten);
    }
}

